      out.write("<!-- Script -->\r\n");
      out.write("<script>\r\n");
      out.write("  document.addEventListener('DOMContentLoaded', function() {\r\n");
      out.write("    // Script cho nút \"Thêm mới\"\r\n");
      out.write("    const addNewBtn = document.querySelector('.btn-primary[data-bs-target=\"#newOrderModal\"]');\r\n");
      out.write("    addNewBtn.addEventListener('click', function() {\r\n");
      out.write("      const modal = new bootstrap.Modal(document.getElementById('newOrderModal'));\r\n");
      out.write("      modal.show();\r\n");
      out.write("      updateOrderSummary();\r\n");
      out.write("    const closeModal = document.querySelector('.btn-close');\r\n");
      out.write("      closeModal.addEventListener('click', function() {\r\n");
      out.write("        $('#modal').modal('hide');\r\n");
      out.write("      });\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    /**\r\n");
      out.write("     * Bật/tắt trạng thái chọn của tất cả các checkbox đơn hàng.\r\n");
      out.write("     * @param {HTMLInputElement} masterCheckbox Checkbox tổng ở tiêu đề bảng.\r\n");
      out.write("     */\r\n");
      out.write("    function toggleSelectAllorder(masterCheckbox) {\r\n");
      out.write("      // 1. Tìm tất cả các checkbox của từng đơn hàng trong tbody\r\n");
      out.write("      //    Lưu ý: class '.supplier-checkbox' là class bạn đã dùng cho các checkbox ở dòng.\r\n");
      out.write("      const rowCheckboxes = document.querySelectorAll('#orderTableBody .supplier-checkbox');\r\n");
      out.write("\r\n");
      out.write("      // 2. Lặp qua từng checkbox và đặt trạng thái 'checked' của nó\r\n");
      out.write("      //    giống với trạng thái của checkbox tổng.\r\n");
      out.write("      rowCheckboxes.forEach(checkbox => {\r\n");
      out.write("        checkbox.checked = masterCheckbox.checked;\r\n");
      out.write("      });\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    /**\r\n");
      out.write("     * Bật/tắt trạng thái \"đánh dấu sao\" của tất cả các đơn hàng.\r\n");
      out.write("     * @param {HTMLElement} masterStar Icon ngôi sao tổng ở tiêu đề bảng.\r\n");
      out.write("     */\r\n");
      out.write("    function toggleSelectAllorderStars(masterStar) {\r\n");
      out.write("      // 1. Xác định xem hành động cần làm là \"tô màu\" hay \"bỏ tô màu\"\r\n");
      out.write("      //    dựa vào trạng thái hiện tại của ngôi sao tổng.\r\n");
      out.write("      //    Nếu ngôi sao tổng là rỗng (có class 'bi-star'), thì chúng ta cần tô màu.\r\n");
      out.write("      const shouldBeFilled = masterStar.classList.contains('bi-star');\r\n");
      out.write("\r\n");
      out.write("      // 2. Tìm tất cả các icon ngôi sao của từng đơn hàng trong tbody\r\n");
      out.write("      const rowStars = document.querySelectorAll('#orderTableBody .bi-star, #orderTableBody .bi-star-fill');\r\n");
      out.write("\r\n");
      out.write("      // 3. Lặp qua từng ngôi sao và thay đổi class của nó\r\n");
      out.write("      rowStars.forEach(star => {\r\n");
      out.write("        if (shouldBeFilled) {\r\n");
      out.write("          // Tô màu ngôi sao\r\n");
      out.write("          star.classList.remove('bi-star');\r\n");
      out.write("          star.classList.add('bi-star-fill', 'text-warning'); // Thêm class màu vàng\r\n");
      out.write("        } else {\r\n");
      out.write("          // Bỏ tô màu ngôi sao\r\n");
      out.write("          star.classList.remove('bi-star-fill', 'text-warning');\r\n");
      out.write("          star.classList.add('bi-star');\r\n");
      out.write("        }\r\n");
      out.write("      });\r\n");
      out.write("\r\n");
      out.write("      // 4. Cập nhật lại chính ngôi sao tổng\r\n");
      out.write("      if (shouldBeFilled) {\r\n");
      out.write("        masterStar.classList.remove('bi-star');\r\n");
      out.write("        masterStar.classList.add('bi-star-fill', 'text-warning');\r\n");
      out.write("      } else {\r\n");
      out.write("        masterStar.classList.remove('bi-star-fill', 'text-warning');\r\n");
      out.write("        masterStar.classList.add('bi-star');\r\n");
      out.write("      }\r\n");
      out.write("    }\r\n");
      out.write("    // Script cho nút \"Gộp đơn\"\r\n");
      out.write("    const mergeOrderBtn = document.querySelector('.btn-success');\r\n");
      out.write("    mergeOrderBtn.addEventListener('click', function() {\r\n");
      out.write("      const selectedOrders = document.querySelectorAll('tbody input[type=\"checkbox\"]:checked');\r\n");
      out.write("      if (selectedOrders.length < 2) {\r\n");
      out.write("        alert('Vui lòng chọn ít nhất 2 đơn hàng để gộp!');\r\n");
      out.write("        return;\r\n");
      out.write("      }\r\n");
      out.write("      const orderIds = Array.from(selectedOrders).map(checkbox =>\r\n");
      out.write("              checkbox.closest('tr').querySelector('td:nth-child(3)')?.textContent?.trim() || ''\r\n");
      out.write("      ).filter(id => id); // Lọc bỏ các ID rỗng\r\n");
      out.write("\r\n");
      out.write("      // Xóa modal cũ nếu tồn tại\r\n");
      out.write("      const existingModal = document.getElementById('mergeOrderModal');\r\n");
      out.write("      if (existingModal) {\r\n");
      out.write("        existingModal.remove();\r\n");
      out.write("      }\r\n");
      out.write("\r\n");
      out.write("      // Tạo danh sách HTML cho các đơn hàng được chọn\r\n");
      out.write("      const orderListItems = orderIds.map(id => {\r\n");
      out.write("        const row = Array.from(document.querySelectorAll('tbody tr')).find(tr =>\r\n");
      out.write("                tr.querySelector('td:nth-child(3)')?.textContent?.trim() === id\r\n");
      out.write("        );\r\n");
      out.write("        const total = row ? row.querySelector('td:nth-child(7)')?.textContent?.trim() || 'N/A' : 'N/A';\r\n");
      out.write("        return `\r\n");
      out.write("      <li class=\"list-group-item d-flex justify-content-between align-items-center\">\r\n");
      out.write("        ");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${id}", java.lang.String.class, (jakarta.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write("\r\n");
      out.write("        <span class=\"badge bg-primary rounded-pill\">");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${total}", java.lang.String.class, (jakarta.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write("</span>\r\n");
      out.write("      </li>\r\n");
      out.write("    `;\r\n");
      out.write("      }).join('');\r\n");
      out.write("\r\n");
      out.write("      // Tạo modal động\r\n");
      out.write("      const mergeModal = `\r\n");
      out.write("    <div class=\"modal fade\" id=\"mergeOrderModal\" tabindex=\"-1\" aria-labelledby=\"mergeOrderModalLabel\" aria-hidden=\"true\">\r\n");
      out.write("      <div class=\"modal-dialog\">\r\n");
      out.write("        <div class=\"modal-content\">\r\n");
      out.write("          <div class=\"modal-header\">\r\n");
      out.write("            <h5 class=\"modal-title\" id=\"mergeOrderModalLabel\">Gộp đơn hàng</h5>\r\n");
