      out.write("      <td><input type=\"text\" class=\"form-control product-search product-id\" placeholder=\"Gõ mã...\"></td>\r\n");
      out.write("      <td><input type=\"text\" class=\"form-control product-search product-name\" placeholder=\"hoặc gõ tên...\"></td>\r\n");
      out.write("      <td><input type=\"number\" class=\"form-control product-quantity\" min=\"1\" value=\"0\"></td>\r\n");
