      out.write("      return;\r\n");
      out.write("    }\r\n");
      out.write("    if (!address.trim()) {\r\n");
      out.write("      alert('Vui lòng nhập địa chỉ nhận hàng!');\r\n");
      out.write("      return;\r\n");
      out.write("    }\r\n");
      out.write("    if (products.length === 0 || products.some(p => !p.toyId || p.quantity <= 0)) {\r\n");
      out.write("      alert('Đơn hàng phải có ít nhất một sản phẩm hợp lệ với số lượng lớn hơn 0!');\r\n");
      out.write("      return;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    // Tạo đối tượng JSON để gửi đi\r\n");
      out.write("    const orderData = {\r\n");
      out.write("      orderCode,\r\n");
      out.write("      customerId,\r\n");
      out.write("      orderDate,\r\n");
      out.write("      address,\r\n");
