      out.write("                  const statusSelectWrapper = document.querySelector('.status-select-wrapper');\r\n");
      out.write("                  if (updateButton && statusDisplay && statusSelect && statusSelectWrapper) {\r\n");
      out.write("                    statusDisplay.onclick = function() {\r\n");
      out.write("                      statusDisplay.style.display = 'none';\r\n");
      out.write("                      statusSelect.classList.add('show');\r\n");
