      out.write("                      statusSelect.classList.remove('show');\r\n");
      out.write("                    };\r\n");
      out.write("                    updateButton.onclick = function() {\r\n");
      out.write("                      const newStatus = statusInput.value;\r\n");
      out.write("                      updateOrderStatus(orderId, newStatus);\r\n");
      out.write("                    };\r\n");
      out.write("                  } else {\r\n");
      out.write("                    console.error('Không tìm thấy phần tử cần thiết để gán sự kiện');\r\n");
      out.write("                    alert('Lỗi: Không thể gán sự kiện cập nhật trạng thái!');\r\n");
      out.write("                    return;\r\n");
      out.write("                  }\r\n");
      out.write("\r\n");
      out.write("                  const modal = new bootstrap.Modal(document.getElementById('orderDetailModal'));\r\n");
      out.write("                  modal.show();\r\n");
      out.write("                } else {\r\n");
      out.write("                  alert('Không tìm thấy thông tin đơn hàng!');\r\n");
      out.write("                }\r\n");
      out.write("              } catch (e) {\r\n");
      out.write("                console.error('Lỗi xử lý phản hồi:', e.message);\r\n");
      out.write("                alert('Lỗi: Không thể phân tích phản hồi từ server!');\r\n");
      out.write("              }\r\n");
      out.write("            })\r\n");
      out.write("            .catch(error => {\r\n");
      out.write("              console.error('Lỗi khi lấy chi tiết:', error);\r\n");
      out.write("              alert('Lỗi khi lấy thông tin: ' + error.message);\r\n");
      out.write("            });\r\n");
      out.write("  }\r\n");
      out.write("  // --- SỬ DỤNG EVENT DELEGATION ĐỂ GẮN SỰ KIỆN CLICK ---\r\n");
      out.write("  // Đoạn code này thay thế cho code cũ của bạn\r\n");
      out.write("  $('#orderTableBody').on('click', '.order-code', function() {\r\n");
      out.write("    // `this` ở đây chính là thẻ <td> có class .order-code được click\r\n");
      out.write("    const orderId = $(this).data('order-id');\r\n");
      out.write("\r\n");
      out.write("    if (orderId) {\r\n");
      out.write("      // Gọi hàm fetchOrderDetails với ID lấy được\r\n");
      out.write("      fetchOrderDetails(orderId);\r\n");
      out.write("    } else {\r\n");
      out.write("      console.error(\"Không tìm thấy order-id trên phần tử được click.\");\r\n");
      out.write("    }\r\n");
      out.write("  });\r\n");
      out.write("//Loc va tim kiem\r\n");
      out.write("  $(document).ready(function() {\r\n");
      out.write("\r\n");
      out.write("    const searchInput = $('#searchInput');\r\n");
      out.write("    const statusFilter = $('#searchStatus');\r\n");
      out.write("    const dateFilter = $('input[type=\"date\"]');\r\n");
      out.write("    const tableBody = $('#orderTableBody');\r\n");
      out.write("    // Thêm các element phân trang nếu có\r\n");
      out.write("    const paginationContainer = $('.pagination-container'); // Thay .pagination-container bằng selector thực tế của bạn\r\n");
      out.write("\r\n");
      out.write("    let currentPage = 1;\r\n");
      out.write("    let debounceTimeout;\r\n");
      out.write("    // Hàm lấy class CSS cho badge trạng thái\r\n");
      out.write("    // Hàm chính: Gọi AJAX để lấy dữ liệu và render lại bảng + phân trang\r\n");
      out.write("    function fetchAndRenderOrders(page = 1) {\r\n");
      out.write("      currentPage = page;\r\n");
      out.write("      const searchTerm = searchInput.val();\r\n");
      out.write("      const status = statusFilter.val();\r\n");
      out.write("      const date = dateFilter.val();\r\n");
      out.write("\r\n");
      out.write("      // Hiển thị hiệu ứng tải (tùy chọn)\r\n");
      out.write("      tableBody.html('<tr><td colspan=\"8\" class=\"text-center\">Đang tải dữ liệu...</td></tr>');\r\n");
      out.write("\r\n");
      out.write("      $.ajax({\r\n");
      out.write("        url: 'order', // URL đến servlet\r\n");
      out.write("        type: 'GET',\r\n");
      out.write("        data: {\r\n");
      out.write("          action: 'searchAndFilter', // Action mới đã định nghĩa ở servlet\r\n");
      out.write("          searchTerm: searchTerm,\r\n");
      out.write("          status: status,\r\n");
      out.write("          date: date,\r\n");
      out.write("          page: currentPage\r\n");
      out.write("        },\r\n");
      out.write("        dataType: 'json',\r\n");
      out.write("        success: function(response) {\r\n");
      out.write("          console.log(\"1. Success callback được gọi!\"); // Log số 1\r\n");
      out.write("          console.log(\"Dữ liệu nhận được:\", response);  // Log số 2\r\n");
      out.write("\r\n");
      out.write("          tableBody.empty(); // Xóa nội dung cũ\r\n");
      out.write("\r\n");
      out.write("          // Render lại các hàng của bảng\r\n");
      out.write("          if (response.orders && response.orders.length > 0) {\r\n");
      out.write("            console.log(\"3. Bắt đầu lặp qua \" + response.orders.length + \" đơn hàng.\"); // Log số 3\r\n");
      out.write("\r\n");
      out.write("            $.each(response.orders, function(index, order) {\r\n");
      out.write("              console.log(\"Đang xử lý đơn hàng:\", order.formattedId); // Log mỗi lần lặp\r\n");
      out.write("              const formattedAmount = new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(order.totalAmount);\r\n");
      out.write("              const row = `\r\n");
      out.write("        <tr>\r\n");
      out.write("            <td><input type=\"checkbox\" class=\"form-check-input supplier-checkbox\" title=\"Chọn nhà cung cấp này\" onclick=\"event.stopPropagation();\"></td>\r\n");
      out.write("            <td><i class=\"bi bi-star star-outline\" onclick=\"toggleSupplierStar(this, event)\"></i></td>\r\n");
      out.write("            <td style=\"color: #0D6EFD; cursor: pointer;\" class=\"order-code\" data-order-id=\"${order.id}\">${order.formattedId}</td>\r\n");
      out.write("            <td>${order.orderDate}</td>\r\n");
      out.write("            <td>${order.customerName}</td>\r\n");
      out.write("\r\n");
      out.write("            ");
      out.write("\r\n");
      out.write("            <td>${order.address}</td>\r\n");
      out.write("\r\n");
      out.write("            <td class=\"text-end\">${formattedAmount}</td>\r\n");
      out.write("            <td class=\"text-center\">\r\n");
      out.write("                <span class=\"status-badge status-${order.status}\">\r\n");
      out.write("                    ${order.statusDisplay}\r\n");
      out.write("                </span>\r\n");
      out.write("            </td>\r\n");
      out.write("        </tr>\r\n");
      out.write("    `;\r\n");
      out.write("\r\n");
      out.write("              console.log(\"HTML của dòng được tạo:\", row); // Log chuỗi HTML\r\n");
      out.write("              tableBody.append(row);\r\n");
      out.write("            });\r\n");
      out.write("          } else {\r\n");
      out.write("            console.log(\"3. Không có đơn hàng nào để hiển thị.\"); // Log nếu không có dữ liệu\r\n");
      out.write("            tableBody.html('<tr><td colspan=\"8\" class=\"text-center\">Không tìm thấy đơn hàng nào khớp với điều kiện.</td></tr>');\r\n");
      out.write("          }\r\n");
      out.write("\r\n");
      out.write("\r\n");
      out.write("          // Render lại phần phân trang\r\n");
      out.write("          renderPagination(response.totalPages, response.currentPage);\r\n");
      out.write("        },\r\n");
      out.write("        error: function(xhr, status, error) {\r\n");
      out.write("          tableBody.html('<tr><td colspan=\"8\" class=\"text-center text-danger\">Có lỗi xảy ra khi tải dữ liệu.</td></tr>');\r\n");
      out.write("          console.error(\"Lỗi AJAX: \", error);\r\n");
      out.write("        }\r\n");
      out.write("      });\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    // Hàm render lại các nút phân trang\r\n");
      out.write("    // HÃY THAY THẾ TOÀN BỘ HÀM CŨ BẰNG HÀM NÀY\r\n");
      out.write("\r\n");
      out.write("    function renderPagination(totalPages, currentPage) {\r\n");
      out.write("      // Chuyển đổi currentPage sang kiểu số để đảm bảo các phép toán chính xác\r\n");
      out.write("      currentPage = parseInt(currentPage);\r\n");
      out.write("\r\n");
      out.write("      // Xóa các nút phân trang cũ\r\n");
      out.write("      paginationContainer.empty();\r\n");
      out.write("\r\n");
      out.write("      // Nếu chỉ có 1 trang hoặc không có trang nào, không cần hiển thị phân trang\r\n");
      out.write("      if (totalPages <= 1) {\r\n");
      out.write("        return;\r\n");
      out.write("      }\r\n");
      out.write("\r\n");
      out.write("      let paginationHtml = '<ul class=\"pagination\">';\r\n");
      out.write("\r\n");
      out.write("      // 1. NÚT \"TRƯỚC\" (PREVIOUS)\r\n");
      out.write("      paginationHtml += `<li class=\"page-item ${currentPage === 1 ? 'disabled' : ''}\">\r\n");
      out.write("                           <a class=\"page-link\" href=\"#\" data-page=\"${currentPage - 1}\">Trước</a>\r\n");
      out.write("                       </li>`;\r\n");
      out.write("\r\n");
      out.write("      // 2. LOGIC HIỂN THỊ CÁC NÚT SỐ TRANG\r\n");
      out.write("\r\n");
      out.write("      // Ngưỡng để quyết định khi nào nên dùng dấu \"...\"\r\n");
      out.write("      const pageThreshold = 7;\r\n");
      out.write("\r\n");
      out.write("      if (totalPages <= pageThreshold) {\r\n");
      out.write("        // TRƯỜNG HỢP 1: TỔNG SỐ TRANG ÍT, HIỂN THỊ TẤT CẢ\r\n");
      out.write("        for (let i = 1; i <= totalPages; i++) {\r\n");
      out.write("          paginationHtml += `<li class=\"page-item ${i === currentPage ? 'active' : ''}\">\r\n");
      out.write("                                   <a class=\"page-link\" href=\"#\" data-page=\"${i}\">${i}</a>\r\n");
      out.write("                               </li>`;\r\n");
      out.write("        }\r\n");
      out.write("      } else {\r\n");
      out.write("        // TRƯỜNG HỢP 2: TỔNG SỐ TRANG NHIỀU, DÙNG DẤU \"...\"\r\n");
      out.write("        // Luôn hiển thị trang đầu tiên\r\n");
      out.write("        paginationHtml += `<li class=\"page-item ${currentPage === 1 ? 'active' : ''}\">\r\n");
      out.write("                               <a class=\"page-link\" href=\"#\" data-page=\"1\">1</a>\r\n");
      out.write("                           </li>`;\r\n");
      out.write("\r\n");
      out.write("        // Xử lý dấu \"...\" bên trái\r\n");
      out.write("        if (currentPage > 4) {\r\n");
      out.write("          paginationHtml += `<li class=\"page-item disabled\"><span class=\"page-link\">...</span></li>`;\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        // Xác định các trang ở giữa để hiển thị\r\n");
      out.write("        let startPage, endPage;\r\n");
      out.write("        if (currentPage <= 4) {\r\n");
      out.write("          // Gần đầu: hiển thị từ 2 đến 5\r\n");
      out.write("          startPage = 2;\r\n");
      out.write("          endPage = 5;\r\n");
      out.write("        } else if (currentPage >= totalPages - 3) {\r\n");
      out.write("          // Gần cuối: hiển thị 4 trang cuối cùng trước trang cuối\r\n");
      out.write("          startPage = totalPages - 4;\r\n");
      out.write("          endPage = totalPages - 1;\r\n");
      out.write("        } else {\r\n");
      out.write("          // Ở giữa: hiển thị trang trước, trang hiện tại, và trang sau\r\n");
      out.write("          startPage = currentPage - 1;\r\n");
      out.write("          endPage = currentPage + 1;\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        for (let i = startPage; i <= endPage; i++) {\r\n");
      out.write("          paginationHtml += `<li class=\"page-item ${i === currentPage ? 'active' : ''}\">\r\n");
      out.write("                                   <a class=\"page-link\" href=\"#\" data-page=\"${i}\">${i}</a>\r\n");
      out.write("                               </li>`;\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
